preset.warp:
uniform sampler2D sampler_cover;
// The theme's accent, one pixel wide (see the app's
// services/milkdrop/textures.ts).
uniform sampler2D sampler_accent;
vec3 accent() {
  return texture(sampler_accent, vec2(0.5)).rgb;
}
// The screen's shorter side in the square units of (uv - 0.5) * aspect.xy,
// relative to a 16:9 window's: covers are sized against the height, so a
// 21:9 screen does not blow them up.
float shortSide() {
  return min(aspect.x, aspect.y) / 0.5625;
}
// Where the cover is, as texture coordinates: the screen's height,
// centred, its sides fading out over `soft` - on a wide screen the rest is
// left to the flow.
vec2 heightCover(vec2 at) {
  return (at - 0.5) * aspect.xy / (0.5625 * shortSide()) + 0.5;
}
float inside(vec2 cuv, float soft) {
  vec2 e = smoothstep(0.0, soft, cuv) * smoothstep(0.0, soft, 1.0 - cuv);
  return e.x * e.y;
}
vec3 tint(vec3 c) {
  float l = dot(c, vec3(0.30, 0.52, 0.18));
  return mix(c, accent() * l * 1.6, 0.35);
}
 shader_body {
  vec3 prev = texture(sampler_main, uv).rgb;
  // The trail takes on the accent as it spreads, then fades.
  prev = mix(prev, tint(prev), 0.06) * 0.985 - 0.002;
  vec2 c = (uv_orig - 0.5) * aspect.xy;
  vec2 cuv = c / (2.0 * q2 * shortSide()) + 0.5;
  vec2 e = smoothstep(0.0, 0.025, cuv) * smoothstep(0.0, 0.025, 1.0 - cuv);
  vec3 cover = texture(sampler_cover, clamp(cuv, 0.0, 1.0)).rgb;
  ret = mix(prev, cover, e.x * e.y * q1);
 }

preset.comp:
uniform sampler2D sampler_cover;
// The theme's accent, one pixel wide (see the app's
// services/milkdrop/textures.ts).
uniform sampler2D sampler_accent;
vec3 accent() {
  return texture(sampler_accent, vec2(0.5)).rgb;
}
// The screen's shorter side in the square units of (uv - 0.5) * aspect.xy,
// relative to a 16:9 window's: covers are sized against the height, so a
// 21:9 screen does not blow them up.
float shortSide() {
  return min(aspect.x, aspect.y) / 0.5625;
}
// Where the cover is, as texture coordinates: the screen's height,
// centred, its sides fading out over `soft` - on a wide screen the rest is
// left to the flow.
vec2 heightCover(vec2 at) {
  return (at - 0.5) * aspect.xy / (0.5625 * shortSide()) + 0.5;
}
float inside(vec2 cuv, float soft) {
  vec2 e = smoothstep(0.0, soft, cuv) * smoothstep(0.0, soft, 1.0 - cuv);
  return e.x * e.y;
}
vec3 tint(vec3 c) {
  float l = dot(c, vec3(0.30, 0.52, 0.18));
  return mix(c, accent() * l * 1.6, 0.35);
}
 shader_body {
  vec3 col = texture(sampler_main, uv).rgb;
  vec3 glow = (texture(sampler_blur1, uv).rgb * scale1 + bias1);
  col += glow * 0.35;
  // The cover itself sharp on top, so the middle never smears away.
  vec2 c = (uv - 0.5) * aspect.xy;
  vec2 cuv = c / (2.0 * q2 * shortSide()) + 0.5;
  vec2 e = smoothstep(0.0, 0.01, cuv) * smoothstep(0.0, 0.01, 1.0 - cuv);
  // Outside the cover: how far from its edge, for a shadow it casts on
  // the trails and an edge of light that flares with each beat.
  float d = length(max(abs(cuv - 0.5) - 0.5, 0.0)) * 2.0 * q2 * shortSide();
  float outside = 1.0 - e.x * e.y;
  col *= 1.0 - 0.6 * exp(-d * 40.0) * outside;
  col += accent() * exp(-d * 160.0) * (0.12 + 0.9 * q3) * outside;
  col = mix(col, texture(sampler_cover, clamp(cuv, 0.0, 1.0)).rgb, e.x * e.y);
  col *= 1.0 - 0.55 * pow(clamp(rad * 1.35, 0.0, 1.0), 2.0);
  ret = col;
 }
